-- HALLEUS_WIKI_SHAHRIVAR_1405_SEO_REFRESH
-- Refresh the already-published shahrivar-1405-transit-guide from the approved SEO package.
-- Preserves stable_id, slug, category, publication state, related IDs, role/cluster/priority and CTA.
-- Synchronizes body_markdown and the public intro/key_points/sections projection, appends one
-- published revision when content changes, increments content_version once, and refreshes inline links.
-- FAQPage JSON-LD is intentionally not added here because the current per-article storage/render contract
-- has no FAQ schema field; the visible FAQ copy remains part of the article.

begin;

do $halleus_shahrivar_schema$
begin
  if to_regclass('public.wiki_articles') is null
    or to_regclass('public.wiki_article_revisions') is null
    or to_regclass('public.wiki_article_drafts') is null
    or to_regclass('public.wiki_internal_links') is null
    or to_regclass('halleus_private.wiki_publish_jobs') is null then
    raise exception 'Wiki storage/CMS migrations must be applied before 0024.';
  end if;
end;
$halleus_shahrivar_schema$;

create temporary table halleus_shahrivar_payload (
  p_title text not null,
  p_short_title text not null,
  p_seo_title text not null,
  p_meta_description text not null,
  p_summary text not null,
  p_body_markdown text not null,
  p_intro text not null,
  p_reading_minutes integer not null,
  p_key_points jsonb not null,
  p_sections jsonb not null,
  p_tags jsonb not null,
  p_context_links jsonb not null,
  p_sources jsonb not null
) on commit drop;

insert into halleus_shahrivar_payload values (
