do $halleus_shahrivar_preflight$
declare
  article_count integer;
  open_draft_count integer;
  active_job_count integer;
  dependency_count integer;
  body_article_link_count integer;
  body_core_link_count integer;
begin
  select count(*)
    into article_count
  from public.wiki_articles
  where stable_id = 'shahrivar-1405-transit-guide';

  if article_count <> 1 then
    raise exception '0024 requires exactly one shahrivar-1405-transit-guide row; found %.', article_count;
  end if;

  if exists (
    select 1
    from public.wiki_articles
    where stable_id = 'shahrivar-1405-transit-guide'
      and slug <> 'shahrivar-1405-transit-guide'
  ) then
    raise exception '0024 refuses to change or repair the canonical slug.';
  end if;

  if not exists (
    select 1
    from public.wiki_articles
    where stable_id = 'shahrivar-1405-transit-guide'
      and status = 'published'
      and is_indexable = true
      and published_at is not null
      and published_at <= now()
      and scheduled_for is null
      and deleted_at is null
  ) then
    raise exception '0024 requires the existing article to be current-public and indexable.';
  end if;

  select count(*)
    into open_draft_count
  from public.wiki_article_drafts draft
  join public.wiki_articles article on article.id = draft.article_id
  where article.stable_id = 'shahrivar-1405-transit-guide';

  if open_draft_count <> 0 then
    raise exception '0024 refuses to overwrite an open draft for shahrivar-1405-transit-guide.';
  end if;

  select count(*)
    into active_job_count
  from halleus_private.wiki_publish_jobs job
  join public.wiki_articles article on article.id = job.article_id
  where article.stable_id = 'shahrivar-1405-transit-guide'
    and job.status in ('queued','running','retry');

  if active_job_count <> 0 then
    raise exception '0024 refuses to race an active publish job for shahrivar-1405-transit-guide.';
  end if;

  select count(*)
    into dependency_count
  from public.wiki_articles
  where stable_id = any(array[
    'planet-sign-house-difference',
    'major-aspects',
    'transits-to-natal-sun-and-moon',
    'why-sun-sign-is-not-enough',
    'mordad-1405-transit-guide',
    'important-transits-tir-1405'
  ]::text[])
    and status = 'published'
    and is_indexable = true
    and published_at is not null
    and published_at <= now()
    and scheduled_for is null
    and deleted_at is null;

  if dependency_count <> 6 then
    raise exception '0024 requires all six embedded article-link targets to be current-public; found %.', dependency_count;
  end if;

  select count(distinct (edge.parts)[1])
    into body_article_link_count
  from halleus_shahrivar_payload payload
  cross join lateral regexp_matches(
    payload.p_body_markdown,
    '\[\[article:([a-z0-9]+(?:[._-][a-z0-9]+)*)(?:\|([^\]\r\n]+))?\]\]',
    'g'
  ) as edge(parts);

  if body_article_link_count <> 6 then
    raise exception '0024 payload must contain exactly six distinct article targets; found %.', body_article_link_count;
  end if;

  select count(*)
    into body_core_link_count
  from halleus_shahrivar_payload payload
  cross join lateral regexp_matches(
    payload.p_body_markdown,
    '\[\[page:(\/(?:chart|compare|sky|wiki)?)(?:\|([^\]\r\n]+))?\]\]',
    'g'
  ) as core_edge(parts);

  if body_core_link_count <> 1 then
    raise exception '0024 payload must contain exactly one core-page link; found %.', body_core_link_count;
  end if;

  if exists (
    select 1
    from halleus_shahrivar_payload payload
    cross join lateral string_to_table(
      replace(payload.p_body_markdown, chr(13), ''),
      chr(10)
    ) as body_line(line_text)
    where body_line.line_text ~ '^#[[:space:]]'
       or body_line.line_text ~ '^#{3,6}[[:space:]]'
       or body_line.line_text ~ '^>'
       or payload.p_body_markdown like '%**%'
       or payload.p_body_markdown like '%```%'
  ) then
    raise exception '0024 payload contains Markdown syntax unsupported by the Wiki parser.';
  end if;

  if jsonb_typeof((select p_key_points from halleus_shahrivar_payload)) <> 'array'
    or jsonb_array_length((select p_key_points from halleus_shahrivar_payload)) <> 3
    or jsonb_typeof((select p_sections from halleus_shahrivar_payload)) <> 'array'
    or jsonb_array_length((select p_sections from halleus_shahrivar_payload)) <> 31
    or jsonb_typeof((select p_tags from halleus_shahrivar_payload)) <> 'array'
    or jsonb_array_length((select p_tags from halleus_shahrivar_payload)) <> 8
    or jsonb_typeof((select p_sources from halleus_shahrivar_payload)) <> 'array'
    or jsonb_array_length((select p_sources from halleus_shahrivar_payload)) <> 3 then
    raise exception '0024 structured payload shape is invalid.';
  end if;
end;
$halleus_shahrivar_preflight$;

lock table public.wiki_articles in share row exclusive mode;
lock table public.wiki_article_revisions in share row exclusive mode;
lock table public.wiki_internal_links in share row exclusive mode;

create temporary table halleus_shahrivar_target on commit drop as
select
  article.*,
  payload.p_title,
  payload.p_short_title,
  payload.p_seo_title,
  payload.p_meta_description,
  payload.p_summary,
  payload.p_body_markdown,
  payload.p_intro,
  payload.p_reading_minutes,
  payload.p_key_points,
  payload.p_sections,
  payload.p_tags,
  payload.p_context_links,
  payload.p_sources,
  article.content_version + 1 as corrected_version,
  (
    article.title is distinct from payload.p_title
    or article.short_title is distinct from payload.p_short_title
    or article.seo_title is distinct from payload.p_seo_title
    or article.meta_description is distinct from payload.p_meta_description
    or article.summary is distinct from payload.p_summary
    or article.body_markdown is distinct from payload.p_body_markdown
    or article.intro is distinct from payload.p_intro
    or article.reading_minutes is distinct from payload.p_reading_minutes
    or article.key_points is distinct from payload.p_key_points
    or article.sections is distinct from payload.p_sections
    or article.tags is distinct from payload.p_tags
    or coalesce(article.context_links, '[]'::jsonb) is distinct from payload.p_context_links
    or coalesce(article.sources, '[]'::jsonb) is distinct from payload.p_sources
  ) as needs_update
from public.wiki_articles article
cross join halleus_shahrivar_payload payload
where article.stable_id = 'shahrivar-1405-transit-guide';

create temporary table halleus_shahrivar_changed on commit drop as
select *
from halleus_shahrivar_target
where needs_update;

with inserted_revisions as (
  insert into public.wiki_article_revisions (
    article_id,
    revision_number,
    snapshot,
    change_note,
    created_by,
    revision_status,
    published_at
  )
  select
    target.id,
    (
      select coalesce(max(existing.revision_number), 0)::integer + 1
      from public.wiki_article_revisions existing
      where existing.article_id = target.id
    ),
    jsonb_build_object(
      'stableId', target.stable_id,
      'slug', target.slug,
      'title', target.p_title,
      'shortTitle', target.p_short_title,
      'seoTitle', target.p_seo_title,
      'metaDescription', target.p_meta_description,
      'categoryId', target.category_id,
      'tags', target.p_tags,
      'summary', target.p_summary,
      'intro', target.p_intro,
      'readingMinutes', target.p_reading_minutes,
      'publicationPriority', target.publication_priority,
      'contentCluster', coalesce(target.content_cluster, target.category_id),
      'articleRole', target.article_role,
      'relatedArticleIds', target.related_article_ids,
      'indexable', target.is_indexable,
      'bodyMarkdown', target.p_body_markdown,
      'keyPoints', target.p_key_points,
      'sections', target.p_sections,
      'contextLinks', target.p_context_links,
      'sources', target.p_sources,
      'callToAction', target.call_to_action,
      'contentVersion', target.corrected_version
    ),
    'Shahrivar 1405 SEO refresh from approved editorial package',
    null,
    'published',
    now()
  from halleus_shahrivar_changed target
  returning article_id
)
update public.wiki_articles article
set
  title = target.p_title,
  short_title = target.p_short_title,
  seo_title = target.p_seo_title,
  meta_description = target.p_meta_description,
  summary = target.p_summary,
  body_markdown = target.p_body_markdown,
  intro = target.p_intro,
  reading_minutes = target.p_reading_minutes,
  key_points = target.p_key_points,
  sections = target.p_sections,
  tags = target.p_tags,
  context_links = target.p_context_links,
  sources = target.p_sources,
  content_version = target.corrected_version
from halleus_shahrivar_changed target
where article.id = target.id
  and exists (
    select 1
    from inserted_revisions revision
    where revision.article_id = article.id
  );

delete from public.wiki_internal_links link
using halleus_shahrivar_changed target
where link.source_article_id = target.id
  and link.link_kind = 'inline';

insert into public.wiki_internal_links (
  source_article_id,
  target_stable_id,
  link_kind,
  source_token
)
select distinct
  target.id,
  (edge.parts)[1],
  'inline',
  '[[article:' || (edge.parts)[1] || ']]'
from halleus_shahrivar_changed target
cross join lateral regexp_matches(
  target.p_body_markdown,
  '\[\[article:([a-z0-9]+(?:[._-][a-z0-9]+)*)(?:\|([^\]\r\n]+))?\]\]',
  'g'
) as edge(parts);

do $halleus_shahrivar_verify$
declare
  changed_count integer;
  inline_count integer;
begin
  select count(*)
    into changed_count
  from halleus_shahrivar_changed;

  if changed_count not in (0, 1) then
    raise exception '0024 changed-row count is invalid: %.', changed_count;
  end if;

  if not exists (
    select 1
    from public.wiki_articles article
    cross join halleus_shahrivar_payload payload
    where article.stable_id = 'shahrivar-1405-transit-guide'
      and article.slug = 'shahrivar-1405-transit-guide'
      and article.status = 'published'
      and article.is_indexable = true
      and article.published_at is not null
      and article.published_at <= now()
      and article.scheduled_for is null
      and article.deleted_at is null
      and article.title = payload.p_title
      and article.short_title = payload.p_short_title
      and article.seo_title = payload.p_seo_title
      and article.meta_description = payload.p_meta_description
      and article.summary = payload.p_summary
      and article.body_markdown = payload.p_body_markdown
      and article.intro = payload.p_intro
      and article.reading_minutes = payload.p_reading_minutes
      and article.key_points = payload.p_key_points
      and article.sections = payload.p_sections
      and article.tags = payload.p_tags
      and coalesce(article.context_links, '[]'::jsonb) = payload.p_context_links
      and coalesce(article.sources, '[]'::jsonb) = payload.p_sources
  ) then
    raise exception '0024 postcondition failed for article content/public projection.';
  end if;

  select count(*)
    into inline_count
  from public.wiki_internal_links link
  join public.wiki_articles article on article.id = link.source_article_id
  where article.stable_id = 'shahrivar-1405-transit-guide'
    and link.link_kind = 'inline';

  if inline_count <> 6 then
    raise exception '0024 expected exactly six inline article-link rows; found %.', inline_count;
  end if;
end;
$halleus_shahrivar_verify$;

commit;
